# ─── Output helpers (style from Prism_pro_111.py lines 89-120) ──────────────


def step(n: int, msg: str) -> None:
    """Emit a numbered step header."""
    print(f"\n{B}[{n}/{TOTAL}] {msg}{NC}")


def ok(msg: str) -> None:
    """Emit a success line (suppressed in --quiet)."""
    if not QUIET_MODE:
        print(f"  {G}✓ {msg}{NC}")


def warn(msg: str) -> None:
    """Emit a warning line (always shown, even in --quiet)."""
    print(f"  {Y}⚠ {msg}{NC}")


def skip(msg: str) -> None:
    """Emit a skip/info line (suppressed in --quiet)."""
    if not QUIET_MODE:
        print(f"  - {msg}")


def dry_log(msg: str) -> None:
    """Emit a dry-run simulated action line."""
    print(f"  {Y}[DRY] would {msg}{NC}")


def write(path: "Path | str", content: str) -> None:
    """
    Write content to path (creating parents).
    Respects DRY_RUN and content-hash skip (O6).
    """
    p = Path(path)
    if DRY_RUN:
        try:
            rel = p.relative_to(HOME)
        except ValueError:
            rel = p
        dry_log(f"write {rel}")
        return
    if not write_if_different(p, content):
        skip(f"{p.name} — unchanged (hash match, skipped)")
        return
    try:
        rel = p.relative_to(HOME)
    except ValueError:
        rel = p
    ok(str(rel))


def backup(path: "Path | str") -> bool:
    """
    Copy path into BACKUP_DIR preserving relative structure.
    Returns True if something was copied, False if source absent.
    """
    p = Path(path)
    if not p.exists():
        return False
    try:
        rel = p.relative_to(CLAUDE_DIR)
    except ValueError:
        rel = Path(p.name)
    dst = BACKUP_DIR / rel
    dst.parent.mkdir(parents=True, exist_ok=True)
    if p.is_dir():
        if dst.exists():
            shutil.rmtree(dst)
        shutil.copytree(str(p), str(dst))
    else:
        shutil.copy2(str(p), str(dst))
    return True


# ─── Global paths ────────────────────────────────────────────────────────────

HOME = Path.home()
# CLAUDE_DIR may be overridden by --target flag (resolved in step_01_parse_flags)
CLAUDE_DIR = HOME / ".claude"

BACKUP_DIR_TEMPLATE = "prism-backup-{date}"
LOCKFILE: Path = CLAUDE_DIR / ".prism-install-lock"  # updated by _init_paths

# Derived dirs (reassigned after --target override)
SKILLS_DIR: Path = CLAUDE_DIR / "skills"
AGENTS_DIR: Path = CLAUDE_DIR / "agents"
HOOKS_DIR: Path = CLAUDE_DIR / "hooks"
CMDS_DIR: Path = CLAUDE_DIR / "commands"
TOOLS_DIR: Path = CLAUDE_DIR / "tools"
PLANS_DIR: Path = CLAUDE_DIR / "plans"
SETTINGS_PATH: Path = CLAUDE_DIR / "settings.json"
CLAUDE_MD_PATH: Path = CLAUDE_DIR / "CLAUDE.md"
BACKUP_DIR: Path = CLAUDE_DIR / BACKUP_DIR_TEMPLATE.format(
    date=datetime.utcnow().strftime("%Y-%m-%d")
)


def _init_paths(claude_dir: Path) -> None:
    """Resolve all derived paths from a (potentially --target-overridden) CLAUDE_DIR."""
    global CLAUDE_DIR, SKILLS_DIR, AGENTS_DIR, HOOKS_DIR, CMDS_DIR, TOOLS_DIR
    global PLANS_DIR, SETTINGS_PATH, CLAUDE_MD_PATH, BACKUP_DIR, LOCKFILE

    CLAUDE_DIR = claude_dir
    SKILLS_DIR = claude_dir / "skills"
    AGENTS_DIR = claude_dir / "agents"
    HOOKS_DIR = claude_dir / "hooks"
    CMDS_DIR = claude_dir / "commands"
    TOOLS_DIR = claude_dir / "tools"
    PLANS_DIR = claude_dir / "plans"
    SETTINGS_PATH = claude_dir / "settings.json"
    CLAUDE_MD_PATH = claude_dir / "CLAUDE.md"
    LOCKFILE = claude_dir / ".prism-install-lock"
    date_str = datetime.utcnow().strftime("%Y-%m-%d")
    BACKUP_DIR = claude_dir / BACKUP_DIR_TEMPLATE.format(date=date_str)


