# ─── O2 Compiled single-pass rewrite regex state ─────────────────────────────

_REWRITE_PATTERN: "re.Pattern | None" = None
_REWRITE_DICT: "dict[str, str] | None" = None


@lru_cache(maxsize=1)
def build_rewrite_regex() -> "tuple[re.Pattern, dict[str, str]]":
    """
    Build a compiled alternation regex from REWRITE_MAP.
    Tokens sorted longest-first to prevent partial-overlap bugs (O2).
    Returns (compiled_pattern, replacement_dict).
    """
    sorted_map = sorted(REWRITE_MAP, key=lambda pair: len(pair[0]), reverse=True)
    replacement_dict = {old: new for old, new in sorted_map}
    tokens = [re.escape(old) for old, _ in sorted_map]
    pattern = re.compile("|".join(tokens))
    return pattern, replacement_dict


def _ensure_rewrite_compiled() -> None:
    """Populate module-level _REWRITE_PATTERN/_REWRITE_DICT on first use."""
    global _REWRITE_PATTERN, _REWRITE_DICT
    if _REWRITE_PATTERN is None:
        _REWRITE_PATTERN, _REWRITE_DICT = build_rewrite_regex()


