# ─── Lockfile helpers ─────────────────────────────────────────────────────────


def acquire_lock() -> bool:
    """
    Create LOCKFILE containing PID + ISO-8601-UTC timestamp.
    If lockfile exists: checks if owning PID is alive (via psutil or os.kill).
    Stale (dead PID) lock: warn + remove + continue.
    Live lock: raises RuntimeError.
    Returns True on success.
    """
    if DRY_RUN:
        skip("--dry-run: skipping lockfile acquire")
        return True

    if LOCKFILE.exists():
        try:
            lock_data = json.loads(LOCKFILE.read_text(encoding="utf-8"))
            pid = int(lock_data.get("pid", 0))
            pid_alive = False
            try:
                import psutil  # noqa: PLC0415
                pid_alive = psutil.pid_exists(pid)
            except ImportError:
                try:
                    os.kill(pid, 0)
                    pid_alive = True
                except ProcessLookupError:
                    pid_alive = False
                except PermissionError:
                    pid_alive = True  # can't signal but process exists
            if pid_alive:
                raise RuntimeError(
                    f"Lock held by live process PID {pid}. "
                    "Close all installer instances before retrying. "
                    f"Lock file: {LOCKFILE}"
                )
            warn(f"Stale lockfile from dead PID {pid} — removing and continuing.")
        except (json.JSONDecodeError, KeyError, ValueError):
            warn("Malformed lockfile — removing and continuing.")
        LOCKFILE.unlink(missing_ok=True)

    lock_data = {
        "pid": os.getpid(),
        "timestamp": datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
        "version": PRISM_VERSION,
    }
    LOCKFILE.parent.mkdir(parents=True, exist_ok=True)
    LOCKFILE.write_text(json.dumps(lock_data, indent=2), encoding="utf-8")
    return True


def release_lock() -> None:
    """Remove LOCKFILE unconditionally. Safe to call multiple times."""
    LOCKFILE.unlink(missing_ok=True)


