def detect_active_hooks() -> list[int]:
    """
    Return list of PIDs running atlas-*.mjs or prism-*.mjs hook processes.
    Lazy-imports psutil — only called when MIGRATE_NEEDED is True (O7).
    """
    try:
        import psutil  # noqa: PLC0415
    except ImportError:
        warn("psutil not installed — cannot check for active hook processes. Proceeding.")
        return []

    active_pids: list[int] = []
    for proc in psutil.process_iter(["pid", "cmdline"]):
        try:
            cmdline = proc.info.get("cmdline") or []
            cmdline_str = " ".join(str(c) for c in cmdline)
            if re.search(r"(atlas|prism)-.*\.mjs", cmdline_str):
                active_pids.append(proc.info["pid"])
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue
    return active_pids


# ─── File migration helpers ───────────────────────────────────────────────────


def _verify_copy(src: Path, dst: Path) -> bool:
    """Return True if src and dst have identical SHA-256 digests."""
    return hash_content(src.read_bytes()) == hash_content(dst.read_bytes())


def migrate_file_pair(old: Path, new: Path, dry: bool) -> str:
    """
    Idempotent file migration — three-way branch (retention §5 / arch §4).
    Returns: 'migrated' | 'already_done' | 'would_migrate' | 'skipped'
    Raises RuntimeError on partial migration or integrity failure.
    """
    if new.exists() and not old.exists():
        return "already_done"
    if old.exists() and not new.exists():
        if dry:
            return "would_migrate"
        new.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(old, new)
        if not _verify_copy(old, new):
            new.unlink(missing_ok=True)
            raise RuntimeError(f"Integrity check failed: {old} -> {new}")
        old.unlink()
        return "migrated"
    if old.exists() and new.exists():
        raise RuntimeError(
            f"Partial migration detected: both {old} and {new} present — "
            "manual resolution required before re-running installer."
        )
    return "skipped"  # neither exists


def migrate_dir(old: Path, new: Path, dry: bool) -> str:
    """
    Idempotent directory migration — same three-way contract as migrate_file_pair.
    Returns: 'migrated' | 'already_done' | 'would_migrate' | 'skipped'
    """
    if new.exists() and not old.exists():
        return "already_done"
    if old.exists() and not new.exists():
        if dry:
            return "would_migrate"
        new.parent.mkdir(parents=True, exist_ok=True)
        shutil.copytree(str(old), str(new))
        shutil.rmtree(str(old))
        return "migrated"
    if old.exists() and new.exists():
        raise RuntimeError(
            f"Partial migration detected: both {old} and {new} present — "
            "manual resolution required."
        )
    return "skipped"


def migrate_state_file(old: Path, new: Path, check: str, dry: bool) -> str:
    """
    Copy state file old -> new, verify integrity, remove original only on pass.
    check in {'row_count', 'line_count', 'json_parse', 'presence', 'file_hash'}
    Returns: 'migrated' | 'already_done' | 'would_migrate' | 'skipped'
    Raises RuntimeError on integrity failure (original left intact).
    """
    if new.exists() and not old.exists():
        return "already_done"
    if not old.exists() and not new.exists():
        return "skipped"
    if old.exists() and new.exists():
        raise RuntimeError(
            f"Partial migration: both {old} and {new} present — resolve manually."
        )
    # old exists, new does not
    if dry:
        return "would_migrate"

    new.parent.mkdir(parents=True, exist_ok=True)
    if old.is_dir():
        shutil.copytree(str(old), str(new))
    else:
        shutil.copy2(str(old), str(new))

    # Verify integrity
    ok_verify = False
    if check == "file_hash":
        ok_verify = _verify_copy(old, new)
    elif check == "line_count":
        old_lines = old.read_text(encoding="utf-8", errors="replace").count("\n")
        new_lines = new.read_text(encoding="utf-8", errors="replace").count("\n")
        ok_verify = old_lines == new_lines
    elif check == "json_parse":
        try:
            json.loads(new.read_text(encoding="utf-8"))
            ok_verify = True
        except json.JSONDecodeError:
            ok_verify = False
    elif check == "presence":
        ok_verify = new.exists()
    elif check == "row_count":
        # Full SQLite row-count comparison handled by verify_sqlite().
        # Here: presence + non-zero size as copy integrity guard.
        ok_verify = new.exists() and new.stat().st_size > 0
    else:
        raise ValueError(f"Unknown integrity check type: {check!r}")

    if not ok_verify:
        if new.is_dir():
            shutil.rmtree(str(new))
        else:
            new.unlink(missing_ok=True)
        raise RuntimeError(
            f"Integrity check '{check}' FAILED for {old} -> {new}. "
            "Original left intact."
        )

    # Remove original only after integrity verified
    if old.is_dir():
        shutil.rmtree(str(old))
    else:
        old.unlink()
    return "migrated"


# ─── String rewriting helpers ─────────────────────────────────────────────────


def _windows_variant(token: str) -> str:
    """
    Return Windows path-separator variant of a POSIX token (arch §5c).
    e.g. 'hooks/atlas-hook.mjs' -> 'hooks\\\\atlas-hook.mjs'
    """
    return token.replace("/", "\\\\")


def _contains_skip_token(text: str, start: int, end: int) -> bool:
    """Return True if the match span overlaps any FTS_SKIP_TOKENS context window."""
    context = text[max(0, start - 20): end + 20]
    return any(tok in context for tok in FTS_SKIP_TOKENS)


def rewrite_file(path: Path, dry: bool) -> dict:
    """
    Read file, apply REWRITE_MAP via single compiled-regex pass (O2).
    Handles POSIX and Windows path separator variants (arch §5c).
    Skips FTS_SKIP_TOKENS context (arch §5a).
    Writes back only if content changed; uses O6 hash check.
    Returns {changed: bool, matches: dict[token, count]}.
    """
    if path.suffix not in EXT_ALLOWLIST:  # O3 extension guard
        return {"changed": False, "matches": {}}

    _ensure_rewrite_compiled()
    assert _REWRITE_PATTERN is not None and _REWRITE_DICT is not None

    try:
        original = path.read_text(encoding="utf-8", errors="replace")
    except PermissionError as exc:
        warn(f"Cannot read {path}: {exc}")
        return {"changed": False, "matches": {}}

    match_counts: dict[str, int] = {}

    def _replacer(m: re.Match) -> str:  # type: ignore[type-arg]
        token = m.group(0)
        if _contains_skip_token(original, m.start(), m.end()):
            return token
        replacement = _REWRITE_DICT[token]  # type: ignore[index]
        match_counts[token] = match_counts.get(token, 0) + 1
        return replacement

    rewritten = _REWRITE_PATTERN.sub(_replacer, original)

    # Second pass: Windows backslash variants (arch §5c)
    win_pairs = [
        (re.escape(_windows_variant(old)), new.replace("/", "\\\\"))
        for old, new in REWRITE_MAP
        if "/" in old
    ]
    if win_pairs:
        win_pattern = re.compile("|".join(p for p, _ in win_pairs))
        win_dict = {
            _windows_variant(old): new.replace("/", "\\\\")
            for old, new in REWRITE_MAP
            if "/" in old
        }

        def _win_replacer(m: re.Match) -> str:  # type: ignore[type-arg]
            token = m.group(0)
            if _contains_skip_token(rewritten, m.start(), m.end()):
                return token
            return win_dict.get(token, token)

        rewritten = win_pattern.sub(_win_replacer, rewritten)

    changed = rewritten != original
    if changed and not dry:
        if not write_if_different(path, rewritten):
            changed = False  # already up to date (hash match)

    return {"changed": changed, "matches": match_counts}


def rewrite_tree(root: Path, globs: list[str], dry: bool) -> dict:
    """
    Recursively rewrite all matching files under root.
    Applies O3 extension allowlist and O4 parallel I/O.
    Returns {files_changed: int, files_skipped: int, total_matches: dict}.
    """
    files_to_process: list[Path] = []
    for pattern in globs:
        files_to_process.extend(root.rglob(pattern))
    files_to_process = list({f for f in files_to_process if f.suffix in EXT_ALLOWLIST})

    files_changed = 0
    files_skipped = 0
    total_matches: dict[str, int] = {}

    max_workers = min(8, os.cpu_count() or 4)
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {executor.submit(rewrite_file, f, dry): f for f in files_to_process}
        for future in futures:
            try:
                result = future.result()
                if result["changed"]:
                    files_changed += 1
                else:
                    files_skipped += 1
                for tok, cnt in result.get("matches", {}).items():
                    total_matches[tok] = total_matches.get(tok, 0) + cnt
            except Exception as exc:  # noqa: BLE001
                warn(f"rewrite_tree error on {futures[future]}: {exc}")

    return {
        "files_changed": files_changed,
        "files_skipped": files_skipped,
        "total_matches": total_matches,
    }


# ─── Settings.json patching ───────────────────────────────────────────────────


def patch_settings_json(path: Path, dry: bool) -> dict:
    """
    Parse settings.json, rewrite atlas-* hook commands + permissions to prism-*.
    Idempotent: if no 'atlas-' substring found, returns {changed: False}.
    Merges — does not overwrite non-atlas keys.
    Returns {changed: bool, keys_patched: int}.
    """
    if not path.exists():
        skip("settings.json not found — nothing to patch")
        return {"changed": False, "keys_patched": 0}

    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        warn(f"settings.json parse error: {exc}")
        return {"changed": False, "keys_patched": 0}

    if "atlas-" not in json.dumps(data):
        return {"changed": False, "keys_patched": 0}

    _ensure_rewrite_compiled()
    assert _REWRITE_PATTERN is not None and _REWRITE_DICT is not None

    keys_patched = 0

    def _patch_value(val: object) -> object:
        nonlocal keys_patched
        if isinstance(val, str) and "atlas-" in val:
            new_val = _REWRITE_PATTERN.sub(  # type: ignore[union-attr]
                lambda m: _REWRITE_DICT.get(m.group(0), m.group(0)), val  # type: ignore[union-attr]
            )
            if new_val != val:
                keys_patched += 1
            return new_val
        elif isinstance(val, list):
            return [_patch_value(item) for item in val]
        elif isinstance(val, dict):
            return {k: _patch_value(v) for k, v in val.items()}
        return val

    patched_data = _patch_value(data)
    new_json = json.dumps(patched_data, indent=2, ensure_ascii=False)

    if dry:
        dry_log(f"patch settings.json ({keys_patched} keys)")
        return {"changed": True, "keys_patched": keys_patched}

    if write_if_different(path, new_json + "\n"):
        ok(f"settings.json patched ({keys_patched} keys updated)")
        return {"changed": True, "keys_patched": keys_patched}

    return {"changed": False, "keys_patched": 0}


# ─── NotebookLM cloud retitle (O5 deferred) ──────────────────────────────────


def retitle_cloud_notebooks(meta_path: Path, dry: bool) -> dict:
    """
    Best-effort retitle of ATLAS-KB:* notebooks to PRISM-KB:* via notebooklm-py.
    On ImportError or missing API: warn + continue (cosmetic operation only).
    Returns {retitled: int, failed: int, skipped: bool}.
    TODO-verify-notebooklm-retitle: confirm notebooklm-py exposes rename_notebook().
    """
    if not meta_path.exists():
        skip("No kb-meta file — cloud notebook retitle skipped")
        return {"retitled": 0, "failed": 0, "skipped": True}

    try:
        meta = json.loads(meta_path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError) as exc:
        warn(f"Cannot read KB meta for retitle: {exc}")
        return {"retitled": 0, "failed": 0, "skipped": True}

    try:
        import notebooklm  # noqa: PLC0415
    except ImportError:
        warn(
            "notebooklm-py not importable — cloud notebook retitle skipped (cosmetic only). "
            "Cloud notebooks keep ATLAS-KB:* titles until manually updated."
        )
        return {"retitled": 0, "failed": 0, "skipped": True}

    rename_fn = getattr(notebooklm, "rename_notebook", None) or getattr(
        notebooklm, "update_title", None
    )
    if rename_fn is None:
        warn(
            "notebooklm-py does not expose rename_notebook()/update_title() — "
            "cloud retitle skipped. Local tooling uses notebook IDs; titles are cosmetic."
        )
        return {"retitled": 0, "failed": 0, "skipped": True}

    if dry:
        nb_count = len(meta.get("notebooks", []))
        dry_log(f"retitle {nb_count} cloud notebooks ATLAS-KB: -> PRISM-KB:")
        return {"retitled": 0, "failed": 0, "skipped": False}

    retitled = 0
    failed = 0
    for nb in meta.get("notebooks", []):
        nb_id = nb.get("id")
        old_title = nb.get("title", "")
        if not nb_id or "ATLAS-KB:" not in old_title:
            continue
        new_title = old_title.replace("ATLAS-KB:", "PRISM-KB:")
        try:
            rename_fn(nb_id, new_title)
            retitled += 1
        except Exception as exc:  # noqa: BLE001
            warn(f"Failed to retitle notebook {nb_id}: {exc}")
            failed += 1

    return {"retitled": retitled, "failed": failed, "skipped": False}


# ─── Integrity & verification helpers ────────────────────────────────────────


def verify_sqlite(db_old: Path, db_new: Path) -> dict:
    """
    Compare row counts for key tables between db_old (backup) and db_new (migrated).
    Skips transcripts_fts (FTS5 virtual table — arch §5a, FTS_SKIP_TOKENS).
    Uses single connection + batched UNION ALL query per DB (O8).
    Returns {table: {old: int, new: int, match: bool}, ...}.
    """
    import sqlite3  # noqa: PLC0415

    # NOTE: transcripts_fts intentionally omitted (FTS5 — arch §5a)
    TABLES_TO_CHECK = ["spend", "model_routing", "sessions", "api_calls", "task_tier_advice"]
    union_query = " UNION ALL ".join(
        f"SELECT '{t}', COUNT(*) FROM {t}" for t in TABLES_TO_CHECK
    )

    def _get_counts(db_path: Path) -> dict[str, int]:
        if not db_path.exists():
            return {}
        try:
            conn = sqlite3.connect(str(db_path))
            cursor = conn.execute(union_query)
            counts = {row[0]: row[1] for row in cursor.fetchall()}
            conn.close()
            return counts
        except sqlite3.Error as exc:
            warn(f"SQLite error on {db_path.name}: {exc}")
            return {}

    old_counts = _get_counts(db_old)
    new_counts = _get_counts(db_new)

    comparison: dict[str, dict] = {}
    for table in TABLES_TO_CHECK:
        old_n = old_counts.get(table, -1)
        new_n = new_counts.get(table, -1)
        comparison[table] = {
            "old": old_n,
            "new": new_n,
            "match": old_n == new_n and old_n >= 0,
        }
    return comparison


def run_test_suite(target: Path) -> "tuple[int, int]":
    """
    Run tools/test-prism-gaps.mjs via node. Returns (passed, total).
    Expects node on PATH.
    """
    _test_env = {**os.environ, "CLAUDE_DIR_OVERRIDE": str(CLAUDE_DIR)}
    test_file = target / "tools" / "test-prism-gaps.mjs"
    if not test_file.exists():
        warn(f"test-prism-gaps.mjs not found at {test_file}")
        return (0, 126)
    try:
        result = subprocess.run(
            ["node", str(test_file)],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=120, env=_test_env,
        )
        output = (result.stdout or '') + (result.stderr or '')
        # test-prism-gaps.mjs prints one of these final-summary lines:
        #   "All <N> assertions passed."   on success (exit 0)
        #   "<F> failed, <P> passed."      on failure (exit 1)
        # The old generic `(\d+)/(\d+)` regex matched unrelated numbers
        # (e.g. "10+5 across two projects") and produced false FATALs.
        m_pass = re.search(r"All\s+(\d+)\s+assertions?\s+passed", output)
        if m_pass:
            total_n = int(m_pass.group(1))
            return (total_n, total_n)
        m_fail = re.search(r"(\d+)\s+failed,\s+(\d+)\s+passed", output)
        if m_fail:
            failed_n = int(m_fail.group(1))
            passed_n = int(m_fail.group(2))
            return (passed_n, failed_n + passed_n)
        # Last-resort fallback — preserved if the test output format changes.
        m = re.search(r"(\d+)/(\d+)", output)
        if m:
            return (int(m.group(1)), int(m.group(2)))
        return (126, 126) if result.returncode == 0 else (0, 126)
    except (subprocess.TimeoutExpired, FileNotFoundError) as exc:
        warn(f"Test suite error: {exc}")
        return (0, 126)


def recall_smoke_test(target: Path) -> bool:
    """
    Run prism-recall.mjs smoke test. Returns True if response is non-empty/non-zero.
    TODO-6.4c: wire to actual prism-recall.mjs invocation once content injected.
    """
    _test_env = {**os.environ, "CLAUDE_DIR_OVERRIDE": str(CLAUDE_DIR)}
    recall_tool = target / "tools" / "prism-recall.mjs"
    if not recall_tool.exists():
        warn(f"prism-recall.mjs not found at {recall_tool}")
        return False
    try:
        result = subprocess.run(
            ["node", str(recall_tool), "what's my total spend this week"],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=30, env=_test_env,
        )
        output = (result.stdout or '') + (result.stderr or '')
        return bool(re.search(r"\$[\d,.]+|[\d]+ token|spend", output, re.IGNORECASE))
    except (subprocess.TimeoutExpired, FileNotFoundError) as exc:
        warn(f"Recall smoke test error: {exc}")
        return False


# ─── O6 content-hash skip helpers ────────────────────────────────────────────


def hash_content(data: "bytes | str") -> str:
    """Return lowercase hex SHA-256 of data (bytes or str)."""
    if isinstance(data, str):
        data = data.encode("utf-8")
    return hashlib.sha256(data).hexdigest()


def write_if_different(path: Path, content: str) -> bool:
    """
    Write content to path only if it differs from the existing file (O6).
    Creates parent dirs. Returns True if written, False if hash-identical (skipped).
    """
    path.parent.mkdir(parents=True, exist_ok=True)
    new_hash = hash_content(content)
    if path.exists():
        try:
            if hash_content(path.read_bytes()) == new_hash:
                return False
        except OSError:
            pass
    path.write_text(content, encoding="utf-8")
    return True


# ─── O1 scoped backup helper ─────────────────────────────────────────────────


def scoped_backup(allowlist: list[str], backup_dir: Path, dry: bool) -> dict:
    """
    Back up only files/dirs in allowlist (relative to CLAUDE_DIR) — not full ~/.claude/ (O1).
    Returns {backed_up: int, skipped: int, total_bytes: int}.
    """
    backed_up = 0
    skipped = 0
    total_bytes = 0

    for rel in allowlist:
        src = CLAUDE_DIR / rel
        if not src.exists():
            skipped += 1
            continue
        dst = backup_dir / rel
        if dry:
            dry_log(f"backup {rel}")
            backed_up += 1
            continue
        dst.parent.mkdir(parents=True, exist_ok=True)
        if src.is_dir():
            if dst.exists():
                shutil.rmtree(dst)
            shutil.copytree(str(src), str(dst))
            for f in dst.rglob("*"):
                if f.is_file():
                    total_bytes += f.stat().st_size
        else:
            shutil.copy2(str(src), str(dst))
            total_bytes += dst.stat().st_size
        backed_up += 1

    return {"backed_up": backed_up, "skipped": skipped, "total_bytes": total_bytes}


# ─── Manifest helper ──────────────────────────────────────────────────────────


def _write_manifest(backup_dir: Path, legacy_info: dict) -> None:
    """
    Write backup manifest to backup_dir/.manifest.json.
    Format per arch §7: timestamp ISO-8601-UTC-Z, sha256 hex, row counts.
    """
    import sqlite3  # noqa: PLC0415

    db_rows: dict[str, int] = {}
    db_sha256 = ""
    db_path = CLAUDE_DIR / ".atlas.db"
    if db_path.exists():
        db_sha256 = hash_content(db_path.read_bytes())
        try:
            conn = sqlite3.connect(str(db_path))
            for table in ["spend", "model_routing", "sessions", "api_calls", "task_tier_advice"]:
                try:
                    row = conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()
                    db_rows[table] = row[0] if row else 0
                except sqlite3.Error:
                    db_rows[table] = -1
            conn.close()
        except sqlite3.Error as exc:
            warn(f"Cannot read .atlas.db for manifest: {exc}")

    sessions_dir = CLAUDE_DIR / ".atlas-sessions"
    sessions_info: dict = {}
    if sessions_dir.exists():
        all_files = [f for f in sessions_dir.rglob("*") if f.is_file()]
        sessions_info = {
            "file_count": len(all_files),
            "total_bytes": sum(f.stat().st_size for f in all_files),
        }

    settings_sha256 = ""
    if SETTINGS_PATH.exists():
        settings_sha256 = hash_content(SETTINGS_PATH.read_bytes())

    manifest = {
        "timestamp": datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
        "installer_version": PRISM_VERSION,
        "file_count": legacy_info.get("count", 0),
        "state_files": {
            ".atlas.db": {"sha256": db_sha256, "rows": db_rows},
            ".atlas-sessions/": sessions_info,
        },
        "settings_json_sha256": settings_sha256,
    }
    manifest_path = backup_dir / ".manifest.json"
    manifest_path.write_text(json.dumps(manifest, indent=2, ensure_ascii=False), encoding="utf-8")


# ─── write_skill_dir helper ───────────────────────────────────────────────────


def write_skill_dir(skill_name: str, files_dict: "dict[str, str]") -> None:
    """
    Write all files for a multi-file skill into SKILLS_DIR/skill_name/.
    files_dict maps relative paths to content strings.
    Idempotent via write_if_different (O6).
    """
    skill_dir = SKILLS_DIR / skill_name
    for rel_path, content in files_dict.items():
        dest = skill_dir / rel_path
        if DRY_RUN:
            dry_log(f"write skills/{skill_name}/{rel_path}")
        else:
            written = write_if_different(dest, content)
            if written:
                ok(f"skills/{skill_name}/{rel_path}")
            else:
                skip(f"skills/{skill_name}/{rel_path} — unchanged")


# ─── Rollback ─────────────────────────────────────────────────────────────────


def do_rollback() -> None:
    """
    Restore CLAUDE_DIR from most recent prism-backup-*/ directory (arch §7).
    Reads .manifest.json to drive restore. Does NOT remove files added post-install.
    Warns: cloud notebook retitles cannot be auto-reverted.
    """
    backup_dirs = sorted(
        [d for d in CLAUDE_DIR.glob("prism-backup-*") if d.is_dir()],
        reverse=True,
    )
    if not backup_dirs:
        print(f"{R}No prism-backup-* directories found under {CLAUDE_DIR}.{NC}")
        sys.exit(1)

    target_backup = backup_dirs[0]

    if not YES_MODE:
        print(f"\nMost recent backup: {target_backup.name}")
        answer = input("Restore from this backup? [y/N] ").strip().lower()
        if answer != "y":
            print("Rollback cancelled.")
            sys.exit(0)

    print(f"\n{B}Rolling back from {target_backup.name}...{NC}")

    restored = 0
    failed = 0
    for src in target_backup.rglob("*"):
        if src.is_dir() or src.name == ".manifest.json":
            continue
        try:
            rel = src.relative_to(target_backup)
            dst = CLAUDE_DIR / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(str(src), str(dst))
            restored += 1
        except Exception as exc:  # noqa: BLE001
            warn(f"Failed to restore {src.name}: {exc}")
            failed += 1

    ok(f"Rollback complete: {restored} files restored, {failed} failed.")
    warn(
        "Rollback does NOT undo NotebookLM cloud retitle operations. "
        "Cloud notebook titles remain PRISM-KB:* until manually reverted."
    )
    if failed > 0:
        sys.exit(1)


# ─── --update-docs pass (arch §9) ────────────────────────────────────────────


def do_update_docs(docs_targets: list[str]) -> None:
    """
    String-replace pass on reader-facing markdown (arch §9).
    Requires --yes or interactive confirmation before applying.
    Never touches CLAUDE.local.md. Only touches paths on explicit --docs-targets list.
    """
    _ensure_rewrite_compiled()

    if not docs_targets:
        docs_targets = [str(CLAUDE_MD_PATH)]

    files_to_patch: list[Path] = []
    for target in docs_targets:
        p = Path(target)
        if not p.exists():
            warn(f"--update-docs target not found: {p}")
            continue
        if p.name == "CLAUDE.local.md":
            skip("Skipping CLAUDE.local.md (private notes — never auto-edited per arch §9)")
            continue
        files_to_patch.append(p)

    if not files_to_patch:
        warn("No valid --update-docs targets found.")
        return

    # Preview
    any_changes = False
    for fpath in files_to_patch:
        result = rewrite_file(fpath, dry=True)
        if result["changed"]:
            any_changes = True
            print(f"\n{Y}Would update {fpath}:{NC}")
            for tok, cnt in result["matches"].items():
                new_tok = _REWRITE_DICT.get(tok, "?") if _REWRITE_DICT else "?"
                print(f"    {tok!r} -> {new_tok!r} ({cnt}x)")

    if not any_changes:
        ok("--update-docs: no changes needed in target files.")
        return

    if not YES_MODE:
        answer = input("\nApply doc updates? [y/N] ").strip().lower()
        if answer != "y":
            print("Doc update cancelled.")
            return

    for fpath in files_to_patch:
        rewrite_file(fpath, dry=False)
        ok(f"Updated {fpath}")
    ok("--update-docs pass complete.")


