def step_01_parse_flags() -> bool:
    """
    Parse CLI flags via argparse; set globals; apply --target override.
    Handles --version early exit.
    Returns True on success.
    """
    global DRY_RUN, ROLLBACK_MODE, VERIFY_MODE, UPDATE_DOCS, YES_MODE, QUIET_MODE
    global _docs_targets

    step(1, "Parse CLI flags")

    parser = argparse.ArgumentParser(
        prog="prism_pro_200",
        description=f"PRISM Code Pro v{PRISM_VERSION} — Unified Installer",
    )
    parser.add_argument("--version", "-v", action="store_true",
                        help="Print version and exit")
    parser.add_argument("--dry-run", action="store_true",
                        help="Simulate install (no writes, no lockfile)")
    parser.add_argument("--rollback", action="store_true",
                        help="Restore from most recent prism-backup-*/")
    parser.add_argument("--verify", action="store_true",
                        help="Run acceptance gates only (steps 22-24) against current state")
    parser.add_argument("--update-docs", action="store_true",
                        help="Additionally run doc-rewrite pass on CLAUDE.md files (arch §9)")
    parser.add_argument("--target", metavar="DIR", default=None,
                        help="Override ~/.claude directory (for 6.5 smoke test on ~/.claude-test/)")
    parser.add_argument("--yes", action="store_true",
                        help="Skip interactive confirmations (for automation)")
    parser.add_argument("--quiet", action="store_true",
                        help="Suppress ok() lines; keep warn()/errors")
    parser.add_argument("--docs-targets", metavar="PATHS", default=None,
                        help="Comma-separated CLAUDE.md paths for --update-docs")

    args = parser.parse_args()

    if args.version:
        print(f"PRISM Code Pro v{PRISM_VERSION} (build {PRISM_BUILD})")
        sys.exit(0)

    DRY_RUN = args.dry_run
    ROLLBACK_MODE = args.rollback
    VERIFY_MODE = args.verify
    UPDATE_DOCS = args.update_docs
    YES_MODE = args.yes
    QUIET_MODE = args.quiet
    _docs_targets = args.docs_targets.split(",") if args.docs_targets else []

    if args.target:
        target_path = Path(args.target).expanduser().resolve()
        _init_paths(target_path)
        ok(f"--target override: CLAUDE_DIR = {CLAUDE_DIR}")

    ok(
        f"PRISM v{PRISM_VERSION} — "
        f"dry={DRY_RUN}, rollback={ROLLBACK_MODE}, verify={VERIFY_MODE}, "
        f"update-docs={UPDATE_DOCS}, yes={YES_MODE}, quiet={QUIET_MODE}"
    )
    return True


def step_02_acquire_lock() -> bool:
    """
    Acquire LOCKFILE. Skipped in --dry-run / --rollback / --verify.
    Returns True on success.
    """
    step(2, "Acquire lockfile")

    if DRY_RUN:
        skip("--dry-run: lockfile not acquired")
        return True
    if ROLLBACK_MODE or VERIFY_MODE:
        skip("rollback/verify mode: lockfile not acquired")
        return True

    result = acquire_lock()
    if result:
        ok(f"Lockfile acquired: {LOCKFILE}")
    return result


def step_03_detect_legacy() -> bool:
    """
    Scan for atlas-* artifacts; set MIGRATE_NEEDED.
    Returns True always (detection is non-fatal).
    """
    step(3, "Detect legacy atlas-* state")

    info = detect_legacy()

    if info["count"] == 0:
        skip("No atlas-* artifacts found — fresh install path")
        ok("MIGRATE_NEEDED = False (O7: Phase 2 migration steps will early-return)")
    else:
        ok(
            f"Found {info['count']} atlas-* artifacts: "
            f"{len(info['files'])} files, {len(info['dirs'])} dirs, "
            f"{len(info['state_files'])} state files"
        )
        ok("MIGRATE_NEEDED = True — Phase 2 migration will run")

    if DRY_RUN:
        _dry_summary["files_to_migrate"] = len(info["files"]) + len(info["dirs"])
        _dry_summary["state_files_to_move"] = len(info["state_files"])

    return True


def step_04_detect_active_hooks() -> bool:
    """
    Check for live atlas-*/prism-* hook processes (arch §5b).
    Skipped entirely if not MIGRATE_NEEDED (O7 lazy legacy).
    Aborts with RuntimeError if active session detected.
    """
    step(4, "Detect active Claude Code session")

    if not MIGRATE_NEEDED:
        skip("No legacy detected (O7) — hook process check skipped")
        return True

    active_pids = detect_active_hooks()
    if active_pids:
        pid_list = ", ".join(str(p) for p in active_pids)
        raise RuntimeError(
            f"Active hook process detected (PID {pid_list}). "
            "Close all Claude Code sessions before running the installer."
        )

    ok("No active hook processes — safe to proceed")
    return True


def step_05_create_backup() -> bool:
    """
    Create scoped backup of files the installer will touch (O1 — not full ~/.claude/).
    Always runs (arch §1 Phase 1). Skipped in --dry-run / --verify / --rollback.
    """
    step(5, "Create scoped backup (O1 — ~55 files, not full ~/.claude/)")

    if DRY_RUN:
        skip("--dry-run: backup creation skipped")
        return True
    if VERIFY_MODE:
        skip("--verify: backup skipped")
        return True
    if ROLLBACK_MODE:
        skip("--rollback: using existing backup")
        return True

    BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    result = scoped_backup(BACKUP_ALLOWLIST, BACKUP_DIR, dry=False)

    ok(
        f"Backup created: {BACKUP_DIR.name} "
        f"({result['backed_up']} items, {result['total_bytes'] // 1024}KB, "
        f"{result['skipped']} absent/skipped)"
    )
    _dry_summary["backup_size_bytes"] = result.get("total_bytes", 0)
    return True


def step_06_write_manifest() -> bool:
    """
    Write backup manifest (file list + SHA-256 + SQLite row counts) to BACKUP_DIR.
    Skipped in --dry-run / --verify / --rollback.
    """
    step(6, "Write backup manifest")

    if DRY_RUN or VERIFY_MODE or ROLLBACK_MODE:
        skip("skipped in this mode")
        return True
    if not BACKUP_DIR.exists():
        warn("Backup dir not found — skipping manifest write")
        return False

    _write_manifest(BACKUP_DIR, _LEGACY_INFO)
    ok(f"Manifest written: {BACKUP_DIR / '.manifest.json'}")
    return True


# ─── PHASE 2 — MIGRATE (steps 7-13, only if MIGRATE_NEEDED) ─────────────────


def step_07_migrate_state_files() -> bool:
    """
    Physical move of 11 state files: copy -> verify -> remove original (retention §4.6).
    Early-returns if not MIGRATE_NEEDED (O7).
    """
    step(7, "Migrate state files (.atlas.* -> .prism.*)")

    if not MIGRATE_NEEDED:
        skip("No legacy detected — skipped (O7)")
        return True

    state_migrations: list[tuple[Path, Path, str]] = [
        (CLAUDE_DIR / ".atlas.db",                 CLAUDE_DIR / ".prism.db",              "row_count"),
        (CLAUDE_DIR / ".atlas-sessions",            CLAUDE_DIR / ".prism-sessions",        "presence"),
        (CLAUDE_DIR / ".atlas-lessons.jsonl",       CLAUDE_DIR / ".prism-lessons.jsonl",   "line_count"),
        (CLAUDE_DIR / ".atlas-kb-index.json",       CLAUDE_DIR / ".prism-kb-index.json",   "json_parse"),
        (CLAUDE_DIR / ".atlas-kb-meta.json",        CLAUDE_DIR / ".prism-kb-meta.json",    "json_parse"),
        (CLAUDE_DIR / ".atlas-spend.jsonl",         CLAUDE_DIR / ".prism-spend.jsonl",     "line_count"),
        (CLAUDE_DIR / ".atlas-model-routing.jsonl", CLAUDE_DIR / ".prism-routing.jsonl",   "line_count"),
        (CLAUDE_DIR / ".atlas-state.json",          CLAUDE_DIR / ".prism-state.json",      "json_parse"),
        (CLAUDE_DIR / ".atlas-context-audit.json", CLAUDE_DIR / ".prism-context-audit.json", "json_parse"),
        (CLAUDE_DIR / ".atlas-context-audit.last", CLAUDE_DIR / ".prism-context-audit.last", "presence"),
        (CLAUDE_DIR / ".atlas-spend.jsonl.bak",    CLAUDE_DIR / ".prism-spend.jsonl.bak",    "line_count"),
        (CLAUDE_DIR / ".atlas-sync-progress.log", CLAUDE_DIR / ".prism-sync-progress.log",  "presence"),
        (CLAUDE_DIR / ".atlas-global-state.json",   CLAUDE_DIR / ".prism-global-state.json", "json_parse"),
        (CLAUDE_DIR / ".atlas-rollups",             CLAUDE_DIR / ".prism-rollups",         "presence"),
        (CLAUDE_DIR / ".atlas-kb-dirty",            CLAUDE_DIR / ".prism-kb-dirty",        "presence"),
    ]

    migrated = already_done = skipped_count = 0
    for old, new, check in state_migrations:
        status = migrate_state_file(old, new, check, dry=DRY_RUN)
        if status == "migrated":
            ok(f"Migrated: {old.name} -> {new.name}")
            migrated += 1
        elif status == "already_done":
            skip(f"Already migrated: {new.name}")
            already_done += 1
        elif status == "would_migrate":
            dry_log(f"migrate state {old.name} -> {new.name}")
            migrated += 1
        else:
            skip(f"Not present: {old.name}")
            skipped_count += 1

    ok(f"State files: {migrated} migrated, {already_done} already done, {skipped_count} absent")
    return True


def step_08_rename_directories() -> bool:
    """
    Rename atlas-* directories to prism-* (retention §2 directory entries).
    Early-returns if not MIGRATE_NEEDED (O7).
    """
    step(8, "Rename directories (atlas-* -> prism-*)")

    if not MIGRATE_NEEDED:
        skip("No legacy detected — skipped (O7)")
        return True

    dir_renames: list[tuple[Path, Path]] = [
        (SKILLS_DIR / "atlas-discover",        SKILLS_DIR / "prism-discover"),
        (SKILLS_DIR / "atlas-plan",             SKILLS_DIR / "prism-plan"),
        (TOOLS_DIR / "atlas-monitor",           TOOLS_DIR / "prism-monitor"),
        (CLAUDE_DIR / "atlas-v1-backup",        CLAUDE_DIR / "prism-v1-backup"),
    ]

