def step_12_retitle_notebooks() -> bool:
    """
    Placeholder step — actual cloud retitle is deferred to background thread (O5).
    Emits notebook count for dry-run summary. Early-returns if not MIGRATE_NEEDED (O7).
    """
    step(12, "Retitle NotebookLM cloud notebooks (deferred O5 background thread)")

    if not MIGRATE_NEEDED:
        skip("No legacy detected — skipped (O7)")
        return True

    if _cloud_thread is not None and _cloud_thread.is_alive():
        skip("Cloud retitle running in background — install continues in parallel")
    else:
        skip("Cloud retitle not started (no meta file, or step 11 skipped)")

    # TODO-verify-notebooklm-retitle: confirm notebooklm-py rename_notebook() API exists
    if DRY_RUN:
        meta_path = CLAUDE_DIR / ".atlas-kb-meta.json"
        if meta_path.exists():
            try:
                meta = json.loads(meta_path.read_text(encoding="utf-8"))
                nb_count = len(meta.get("notebooks", []))
                _dry_summary["cloud_notebooks_to_retitle"] = nb_count
                dry_log(f"retitle {nb_count} cloud notebooks ATLAS-KB: -> PRISM-KB:")
            except (json.JSONDecodeError, OSError):
                pass
    return True


def step_13_integrity_sweep() -> bool:
    """
    Run test-prism-gaps.mjs --dry-run to catch stale atlas-* references.
    Early-returns if not MIGRATE_NEEDED (O7).
    """
    step(13, "Integrity sweep (test-prism-gaps.mjs --dry-run)")

    if not MIGRATE_NEEDED:
        skip("No legacy detected — skipped (O7)")
        return True

    test_file = TOOLS_DIR / "test-prism-gaps.mjs"
    if not test_file.exists():
        warn("test-prism-gaps.mjs not found — integrity sweep skipped")
        return True

    if DRY_RUN:
        dry_log("run test-prism-gaps.mjs --dry-run")
        return True

    _test_env = {**os.environ, "CLAUDE_DIR_OVERRIDE": str(CLAUDE_DIR)}
    try:
        result = subprocess.run(
            ["node", str(test_file), "--dry-run"],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=60, env=_test_env,
        )
        if result.returncode == 0:
            ok("Integrity sweep: no stale atlas-* references found")
        else:
            output = ((result.stdout or '') + (result.stderr or ''))[:2000]
            warn(f"Integrity sweep found issues:\n{output}")
    except (subprocess.TimeoutExpired, FileNotFoundError) as exc:
        warn(f"Integrity sweep skipped: {exc}")

    return True


