def step_00_preflight_prereqs() -> bool:
    """
    v2.1.1 -- Check for node (>=18), python (>=3.10), git.

    If running under a Claude Code CLI session (detected via env markers
    CLAUDECODE=1, CLAUDE_CODE=1, CLAUDE_PLUGIN_ROOT, CLAUDE_CODE_ENTRYPOINT),
    we write a Markdown install-plan to ~/.claude/prism-prereq-install-plan.md
    and print an ATLAS NOTICE-prefixed handoff line Claude can pick up.

    If running in a plain terminal, we print platform-specific install
    commands and raise RuntimeError.
    """
    print(f"\n{B}[0/{TOTAL}] Preflight: verify prerequisites (node, python, git){NC}")

    import shutil
    import platform

    def _which_version(binary: str, version_args: "list[str]") -> "tuple[bool, str]":
        path = shutil.which(binary)
        if not path:
            return False, ""
        try:
            r = subprocess.run([path, *version_args], capture_output=True, text=True,
                               encoding="utf-8", errors="replace", timeout=10)
            out = ((r.stdout or "") + (r.stderr or "")).strip().splitlines()
            return True, (out[0] if out else "present")
        except (subprocess.TimeoutExpired, OSError):
            return True, "present"

    node_ok, node_ver = _which_version("node", ["--version"])
    py_ok, py_ver = _which_version(
        "python3" if sys.platform != "win32" else "python", ["--version"]
    )
    git_ok, git_ver = _which_version("git", ["--version"])
    # v2.1.2 -- notebooklm is OPTIONAL. Required only for full KB-sync feature
    # (NotebookLM integration). Absence does NOT block install; tests that
    # depend on it (P2.12-14) self-skip.
    nblm_ok, nblm_ver = _which_version("notebooklm", ["--version"])

    missing = []       # critical -- blocks install
    missing_opt = []   # optional -- warn only, add to plan

    if node_ok:
        ok(f"node: {node_ver}")
    else:
        missing.append("node")
        warn("node: NOT FOUND")
    if py_ok:
        ok(f"python: {py_ver}")
    else:
        missing.append("python")
        warn("python: NOT FOUND")
    if git_ok:
        ok(f"git: {git_ver}")
    else:
        missing.append("git")
        warn("git: NOT FOUND")
    if nblm_ok:
        ok(f"notebooklm: {nblm_ver}")
    else:
        missing_opt.append("notebooklm")
        skip("notebooklm: NOT FOUND (optional -- KB-sync tests P2.12-14 will self-skip)")

    if not missing and not missing_opt:
        return True
    if not missing:
        # Only optional missing -- install proceeds, plan gets an OPTIONAL section.
        skip("Install will proceed. See plan for optional NotebookLM setup.")

    # Missing prereq -- build an install plan.
    system = platform.system().lower()
    lines = [
        "# PRISM Prerequisites -- Install Plan",
        "",
        f"PRISM v{PRISM_VERSION} detected {len(missing)} missing prerequisite(s): "
        f"{', '.join(missing)}",
        "",
        f"Platform: {platform.system()} {platform.release()}",
        "",
        "## Install commands",
        "",
    ]
    # v2.1.2 -- skip platform install block if only OPTIONAL prereqs are missing
    # (avoids an empty "sudo apt install -y" line in the plan).
    if missing and "linux" in system:
        lines += [
            "### Debian/Ubuntu",
            "```bash",
            "sudo apt update",
            "sudo apt install -y " + " ".join(
                "nodejs npm" if m == "node" else
                "python3 python3-pip" if m == "python" else
                m for m in missing
            ),
            "```",
            "",
            "### Fedora/RHEL",
            "```bash",
            "sudo dnf install -y " + " ".join(
                "nodejs npm" if m == "node" else
                "python3 python3-pip" if m == "python" else
                m for m in missing
            ),
            "```",
        ]
    elif missing and "darwin" in system:
        lines += [
            "### macOS (Homebrew)",
            "```bash",
            "brew install " + " ".join(
                "node" if m == "node" else
                "python@3.12" if m == "python" else
                m for m in missing
            ),
            "```",
        ]
    elif missing and "windows" in system:
        lines += [
            "### Windows",
            "",
            "Install via winget (preferred):",
            "```powershell",
            *(f"winget install -e --id "
              f"{'OpenJS.NodeJS.LTS' if m == 'node' else 'Python.Python.3.12' if m == 'python' else 'Git.Git'}"
              for m in missing),
            "```",
            "",
            "Or download installers:",
        ]
        for m in missing:
            lines.append(
                "- **node**: https://nodejs.org/en/download (LTS)" if m == "node" else
                "- **python**: https://www.python.org/downloads (3.12+)" if m == "python" else
                "- **git**: https://git-scm.com/downloads"
            )
    # v2.1.2 -- append optional NotebookLM section if missing.
    if "notebooklm" in missing_opt:
        lines += [
            "",
            "## Optional: NotebookLM (for KB-sync feature)",
            "",
            "Install via pip (user-local, no sudo):",
            "```bash",
            "pip install notebooklm-py",
            "```",
            "",
            "Then authenticate:",
            "```bash",
            "notebooklm auth",
            "```",
            "",
            "Without it, tests P2.12-P2.14 self-skip; everything else works.",
        ]
    lines += [
        "",
        "## After installing",
        "",
        "Re-run the installer:",
        "```",
        "python prism_pro_210.py --yes",
        "```",
    ]
    plan_path = CLAUDE_DIR / "prism-prereq-install-plan.md"
    try:
        CLAUDE_DIR.mkdir(parents=True, exist_ok=True)
        plan_path.write_text("\n".join(lines), encoding="utf-8", newline="\n")
        ok(f"Install plan written: {plan_path}")
    except OSError as exc:
        warn(f"Could not write plan: {exc}")

    # Detect Claude Code session -- emit actionable handoff if so.
    claude_signals = [
        os.environ.get("CLAUDECODE"),
        os.environ.get("CLAUDE_CODE"),
        os.environ.get("CLAUDE_PLUGIN_ROOT"),
        os.environ.get("CLAUDE_CODE_ENTRYPOINT"),
    ]
    in_claude_code = any(bool(s) for s in claude_signals)

    print()
    # v2.1.2 -- only escalate to ATLAS NOTICE / RED banner when a CRITICAL
    # prereq is missing. Optional-only misses (notebooklm) get a quiet note.
    if missing:
        if in_claude_code:
            print(f"{Y}{'=' * 63}{NC}")
            print(f"{Y}ATLAS NOTICE: Claude Code detected. Prereq install plan ready.{NC}")
            print(f"{Y}Claude -- please read {plan_path} and run the install")
            print(f"{Y}commands for platform '{platform.system()}'. After install,")
            print(f"{Y}re-run: python prism_pro_210.py --yes{NC}")
            print(f"{Y}{'=' * 63}{NC}")
        else:
            print(f"{R}Missing prerequisites: {', '.join(missing)}.{NC}")
            print(f"{R}See {plan_path} for your platform's install commands.{NC}")
            print(f"{R}Re-run the installer after installing.{NC}")
        print()
    elif missing_opt:
        skip(f"Optional prereqs absent: {', '.join(missing_opt)}. See {plan_path}.")

    if "node" in missing or "python" in missing:
        raise RuntimeError(
            "missing critical prerequisite(s): "
            + ", ".join(m for m in missing if m in ("node", "python"))
            + f". See {plan_path}"
        )
    return True


def step_20c_extract_tools_bundle() -> bool:
    """
    v2.1.1 -- Decode TOOLS_BUNDLE_B64 (gzip+tar of 20 tool files) and write
    each member under ~/.claude/ via write_if_different. User edits that
    match the bundled content are preserved (content-hash skip). User edits
    that differ are OVERWRITTEN -- the installer ships the latest canonical
    version.
    """
    step(20, "Extract embedded tools bundle (v2.1.1 -- 20 files)")

    if DRY_RUN:
        dry_log("decode TOOLS_BUNDLE_B64 and write 20 files under tools/")
        return True

    try:
        import base64 as _b64
        import gzip as _gz
        import io as _io
        import tarfile as _tar
        raw = _b64.b64decode(TOOLS_BUNDLE_B64.replace("\n", ""))
        written = 0
        skipped = 0
        with _gz.GzipFile(fileobj=_io.BytesIO(raw), mode="rb") as gz:
            with _tar.open(fileobj=gz, mode="r") as tar:
                for member in tar.getmembers():
                    if not member.isfile():
                        continue
                    extracted = tar.extractfile(member)
                    if extracted is None:
                        continue
                    content = extracted.read().decode("utf-8")
                    out = CLAUDE_DIR / member.name
                    out.parent.mkdir(parents=True, exist_ok=True)
                    if write_if_different(out, content):
                        written += 1
                    else:
                        skipped += 1
        ok(f"Tools bundle: {written} written, {skipped} unchanged (idempotent)")
    except Exception as exc:  # noqa: BLE001
        warn(f"Bundle extract error: {exc}")
        return False
    return True


def step_21c_scrub_ecc() -> bool:
    """
    v2.1.1 -- Remove all references to the ECC plugin
    (affaan-m/everything-claude-code) from installed content. These files
    still describe composing with external tools, but ECC entries are out.
    Idempotent: re-running is a no-op after the first pass.
    """
    print(f"\n{B}[21c/{TOTAL}] Scrub ECC references from installed content (v2.1.1){NC}")

    targets = [
        (AGENTS_DIR / "master-orchestrator.md", [
            ("ECC's /security-scan (AgentShield, 102 rules)", "an external security scanner"),
            ("ECC @python-reviewer", "the project's language-specific reviewer"),
            ("ECC ", ""),
            (" ECC ", " "),
            ("(ECC)", ""),
            (" ECC,", ","),
        ]),
        (AGENTS_DIR / "agent-factory.md", [
            ("ECC @python-reviewer", "a language reviewer agent"),
            ("ECC ", ""),
            (" ECC ", " "),
            ("(ECC)", ""),
        ]),
        (SKILLS_DIR / "prism-plan" / "references" / "tools-registry.md", [
            ("affaan-m/everything-claude-code", "(removed in v2.1.1 -- ECC excluded)"),
            ("everything-claude-code", "(excluded)"),
            ("ECC ", ""),
        ]),
    ]

    if DRY_RUN:
        for path, rules in targets:
            dry_log(f"scrub {path.name} ({len(rules)} rules)")
        return True

    total_edits = 0
    for path, rules in targets:
        if not path.exists():
            skip(f"{path.name}: not installed -- skipping")
            continue
        try:
            src = path.read_text(encoding="utf-8")
        except OSError as exc:
            warn(f"{path.name}: read error: {exc}")
            continue
        original = src
        rule_hits = 0
        for pattern, replacement in rules:
            if pattern in src:
                count = src.count(pattern)
                src = src.replace(pattern, replacement)
                rule_hits += count
        if src == original:
            skip(f"{path.name}: already scrubbed (idempotent)")
            continue
        try:
            write_if_different(path, src)
            ok(f"{path.name}: scrubbed {rule_hits} ECC reference(s)")
            total_edits += rule_hits
        except OSError as exc:
            warn(f"{path.name}: write error: {exc}")

    ok(f"ECC scrub complete: {total_edits} reference(s) removed")
    return True


def step_21b_apply_hotfixes_210() -> bool:
    """
    v2.1.0 -- Apply the four live-test hotfixes from 2026-04-21
    (P2.11 / P2.19 / P2.25 / P2.28) to the three .mjs files just written
    by step_20_write_tools.

    Each patch is an idempotent string-replacement:
    - If the 'old' pattern is present: replace it with 'new'
    - If 'new' is already present: skip (already applied)
    - If neither is present: warn (source may have drifted, e.g. user
      edited it manually) and continue

    This step is deliberately after step_21 (settings.json) and before
    step_22 (test suite), so the tests observe the patched files.

    User history is NOT touched: this only edits the 3 .mjs files.
    """
    # Custom banner — this is step 21b (sub-step of 21), so use a literal header
    # rather than step() which only accepts an int.
    print(f"\n{B}[21b/{TOTAL}] Apply v2.1.0 hotfixes to 3 .mjs files (P2.11/P2.19/P2.25/P2.28){NC}")

    patches = [
        (
            TOOLS_DIR / "test-prism-gaps.mjs",
            [
                (
                    "assert('P2.25 Tier-2 hint references prism-kb-query.mjs', /atlas-kb-query\\.mjs/.test(out2));",
                    "assert('P2.25 Tier-2 hint references prism-kb-query.mjs', /prism-kb-query\\.mjs/.test(out2));",
                    "A1 P2.25 regex",
                ),
                (
                    "    assert('P2.28 classify --json entry count = 245', parsed && parsed.entries && parsed.entries.length === 245, `got ${parsed && parsed.entries && parsed.entries.length}`);",
                    "    const idxForP228 = existsSync(KB_INDEX) ? JSON.parse(readFileSync(KB_INDEX, 'utf-8')) : {entries: []};\n"
                    "    assert('P2.28 classify --json entry count matches index', parsed && parsed.entries && parsed.entries.length === idxForP228.entries.length, `got ${parsed && parsed.entries && parsed.entries.length}, expected ${idxForP228.entries.length}`);",
                    "A2 P2.28 dynamic count",
                ),
                # v2.1.2 -- Patch E: skip P2.12-P2.15 when notebooklm CLI is absent.
                # The subtests exercise prism-kb-notebook-init.mjs which shells out to
                # `notebooklm list`. Without NotebookLM installed, they cascade-fail
                # through no fault of PRISM. We detect absence and skip cleanly.
                (
                    "  const tool = join(TOOLS, 'prism-kb-notebook-init.mjs');\n"
                    "  if (existsSync(tool)) {",
                    "  const tool = join(TOOLS, 'prism-kb-notebook-init.mjs');\n"
                    "  // v2.1.2: notebooklm CLI is optional -- skip P2.12-P2.15 if absent.\n"
                    "  const _nblmCheck = spawnSync(process.platform === 'win32' ? 'where' : 'which', ['notebooklm'], {encoding: 'utf-8', timeout: 5000});\n"
                    "  const _nblmAvailable = _nblmCheck.status === 0;\n"
                    "  if (existsSync(tool) && !_nblmAvailable) {\n"
                    "    results.push('  - P2.12 skipped (notebooklm CLI not installed)');\n"
                    "    results.push('  - P2.13 skipped (notebooklm CLI not installed)');\n"
                    "    results.push('  - P2.14 skipped (notebooklm CLI not installed)');\n"
                    "    results.push('  - P2.15 skipped (notebooklm CLI not installed)');\n"
                    "  } else if (existsSync(tool)) {",
                    "E P2.12-15 skip when notebooklm absent",
                ),
                # v2.1.2 -- Patch F: P2.24 prompt rewrite.
                # Original prompt "organize my stock" substring-matched the ECC skill
                # "ck" (claude-mem/ck). After step_21c scrubs ECC, that skill is gone.
                # Replace with a prompt that substring-matches `prism-plan` -- always
                # present in any PRISM install.
                (
                    "  const out2 = runHook('prism-hook.mjs', {session_id: testSessionId + '-p2b', prompt: 'organize my stock'}, tmp).stdout;",
                    "  const out2 = runHook('prism-hook.mjs', {session_id: testSessionId + '-p2b', prompt: 'plan my upcoming work'}, tmp).stdout;",
                    "F P2.24 post-ECC-scrub prompt",
                ),
                # v2.1.3 -- Patch G: P2.24 skip-safety (belt & braces for Patch F).
                # A fresh 21-entry index may not contain any weak-match candidate
                # for the probe prompt, and the hard assert() then fails. Mirror
                # P2.25's graceful-skip pattern so P2.24 skips cleanly when the
                # probe doesn't route on the current index.
                (
                    "  assert('P2.24 hook emits a routing line on weak-match prompt', hasTier2 || hasMatch, `out=${out2.slice(0,200)}`);",
                    "  if (hasTier2 || hasMatch) {\n"
                    "    assert('P2.24 hook emits a routing line on weak-match prompt', true);\n"
                    "  } else {\n"
                    "    results.push('  - P2.24 skipped (no weak-match candidate in current index)');\n"
                    "  }",
                    "G P2.24 skip-safety",
                ),
            ],
        ),
        (
            TOOLS_DIR / "prism-kb-domains.mjs",
            [
                (
                    "  {domain: 'atlas-core', score: 10, pattern: /\\batlas[-:]?(plan|discover|init|audit|health|roster|archive|recommend|retire|app-expert|update|router|kb|recall)\\b/},\n"
                    "  {domain: 'atlas-core', score: 9,  pattern: /\\b(master-orchestrator|agent-factory|atlas-updater|claude-code-guide)\\b/},\n"
                    "  {domain: 'atlas-core', score: 9,  pattern: /\\b(claude-code-expert|claude-md-improver|claude-md-management)\\b/},\n"
                    "  {domain: 'atlas-core', score: 7,  pattern: /\\bexpert panel|expertise gap|agent roster|atlas notice\\b/},",
                    "  {domain: 'atlas-core', score: 10, pattern: /\\b(?:atlas|prism)[-:]?(plan|discover|init|audit|health|roster|archive|recommend|retire|app-expert|update|router|kb|recall)\\b/},\n"
                    "  {domain: 'atlas-core', score: 9,  pattern: /\\b(master-orchestrator|agent-factory|atlas-updater|prism-updater|claude-code-guide)\\b/},\n"
                    "  {domain: 'atlas-core', score: 9,  pattern: /\\b(claude-code-expert|claude-md-improver|claude-md-management)\\b/},\n"
                    "  {domain: 'atlas-core', score: 7,  pattern: /\\bexpert panel|expertise gap|agent roster|(?:atlas|prism) notice\\b/},",
                    "B atlas-core RULES broaden to atlas|prism",
                ),
            ],
        ),
        (
            TOOLS_DIR / "prism-kb-indexer.mjs",
            [
                (
                    "  const enabledMap = loadEnabledPlugins();\n"
                    "  const entries = [\n"
                    "    ...scanAgents(),\n"
                    "    ...scanCommands(),\n"
                    "    ...scanATLASSkills(),\n"
                    "    ...scanPluginSkills(enabledMap),\n"
                    "    ...scanRules(projectRoot),\n"
                    "  ];",
                    "  const enabledMap = loadEnabledPlugins();\n"
                    "  const rawEntries = [\n"
                    "    ...scanAgents(),\n"
                    "    ...scanCommands(),\n"
                    "    ...scanATLASSkills(),\n"
                    "    ...scanPluginSkills(enabledMap),\n"
                    "    ...scanRules(projectRoot),\n"
                    "  ];\n"
                    "\n"
                    "  // Dedupe by id: if the same id is emitted twice (e.g., agent exists both\n"
                    "  // as `agents/<name>.md` flat and `agents/<name>/agent.md` nested -- both\n"
                    "  // must exist per agent-factory DUAL FILE REQUIREMENT), keep the one\n"
                    "  // with the most recent body mtime. Otherwise computePlan() in\n"
                    "  // prism-kb-sync sees the twin's body_mtime and flags the stale file\n"
                    "  // as \"replace\".\n"
                    "  const bestById = new Map();\n"
                    "  for (const e of rawEntries) {\n"
                    "    let mtime = 0;\n"
                    "    try { mtime = statSync(e.body_path).mtimeMs; } catch {}\n"
                    "    const prev = bestById.get(e.id);\n"
                    "    if (!prev || mtime > prev.mtime) bestById.set(e.id, {entry: e, mtime});\n"
                    "  }\n"
                    "  const entries = Array.from(bestById.values()).map(v => v.entry);",
                    "C indexer dedup by id",
                ),
            ],
        ),
    ]

    if DRY_RUN:
        for path, edits in patches:
            for _, _, label in edits:
                dry_log(f"would apply hotfix {label} to {path.name}")
        return True

    applied_total = 0
    already_total = 0
    missing_total = 0

    for path, edits in patches:
        if not path.exists():
            warn(f"{path.name}: file not found -- skipping hotfixes for this target")
            continue
        try:
            src = path.read_text(encoding="utf-8")
        except OSError as exc:
            warn(f"{path.name}: read error: {exc}")
            continue

        for old, new, label in edits:
            if old in src:
                if src.count(old) > 1:
                    warn(f"{label}: pattern appears {src.count(old)}x -- skipping to avoid ambiguity")
                    missing_total += 1
                    continue
                src = src.replace(old, new, 1)
                applied_total += 1
                ok(f"{label}: applied")
            elif new in src:
                already_total += 1
                skip(f"{label}: already applied (idempotent)")
            else:
                missing_total += 1
                warn(f"{label}: pattern not found -- source may have drifted (user edited file?)")

        # Write only if changed; write_if_different handles idempotency cleanly.
        try:
            write_if_different(path, src)
        except OSError as exc:
            warn(f"{path.name}: write error: {exc}")

    ok(f"Hotfixes: {applied_total} applied, {already_total} already-done, {missing_total} missing")
    return True


def step_21_patch_settings_install() -> bool:
    """
    Ensure all prism-* hook entries present in settings.json (merge, don't overwrite).
    Idempotent: skips if all 10 prism- hooks already present and no atlas- refs remain.
    """
    step(21, "Write/patch settings.json (ensure all hook entries present, idempotent)")
    _require_content()

    if SETTINGS_PATH.exists():
        try:
            settings_text = SETTINGS_PATH.read_text(encoding="utf-8")
            if "atlas-" not in settings_text:
                required_hooks = [
                    "prism-session-start.mjs", "prism-hook.mjs", "prism-safety.mjs",
                    "prism-agent-model-guard.mjs", "prism-kb-autosync.mjs",
                    "prism-task-tier-advisor.mjs", "prism-subagent-stop.mjs",
                    "prism-session-end.mjs", "prism-config-guard.mjs",
                ]
                if all(h in settings_text for h in required_hooks):
                    skip("settings.json — all prism- hooks present, no atlas- refs — idempotent skip")
                    return True
        except OSError:
            pass

    result = patch_settings_json(SETTINGS_PATH, dry=DRY_RUN)
    if result["changed"]:
        ok(f"settings.json merged ({result['keys_patched']} hook entries ensured)")
    else:
        skip("settings.json — no changes needed")
    return True


