def step_23_verify_sqlite() -> bool:
    """
    Verify SQLite row counts match backup snapshot (acceptance criterion #4).
    Compares spend, model_routing, sessions, api_calls, task_tier_advice.
    """
    step(23, "SQLite integrity check (row counts vs backup manifest)")

    if DRY_RUN:
        dry_log("verify .prism.db row counts vs .atlas.db pre-migration snapshot")
        return True

    db_new = CLAUDE_DIR / ".prism.db"
    db_old = BACKUP_DIR / ".atlas.db"  # backup copy of original

    if not db_new.exists():
        warn(".prism.db not found — SQLite integrity check skipped")
        return True
    if not db_old.exists():
        skip("No backup .atlas.db — skipping row-count comparison (fresh install?)")
        return True

    comparison = verify_sqlite(db_old, db_new)
    all_match = True
    for table, counts in comparison.items():
        if counts["match"]:
            ok(f"SQLite {table}: {counts['new']} rows (matches backup)")
        else:
            warn(f"SQLite {table}: backup={counts['old']}, migrated={counts['new']} — MISMATCH")
            all_match = False

    if not all_match:
        raise RuntimeError(
            "SQLite row count mismatch detected. "
            "Review .prism.db integrity before proceeding."
        )
    return True


