    """
    Join deferred cloud retitle thread (O5, timeout 30s), release lockfile, emit banner.
    Always runs — even on error (via finally block in main()).
    """
    step(25, "Release lockfile + emit success banner")

    # O5 — Join cloud retitle thread
    if _cloud_thread is not None and _cloud_thread.is_alive():
        skip("Waiting up to 30s for cloud retitle thread...")
