# ═════════════════════════════════════════════════════════════════════════════
# MAIN ORCHESTRATOR
# ═════════════════════════════════════════════════════════════════════════════


def main() -> None:
    """
    Orchestrate all 25 steps.
    Handles CLI flag branching: --dry-run, --rollback, --verify, --update-docs.
    Wraps in try/finally to ensure lockfile released on any error path.
    """
    print()
    print("=" * 60)
    print(f"  PRISM Code Pro v{PRISM_VERSION} — Unified Installer")
    print(f"  Build: {PRISM_BUILD}")
    print("  atlas-* -> prism-* with automatic legacy migration")
    print("=" * 60)

    lock_acquired = False
    try:
        # Step 1 always runs (parses flags, may override CLAUDE_DIR via --target)
        step_01_parse_flags()

        # ── --rollback path ──────────────────────────────────────────────────
        if ROLLBACK_MODE:
            step_02_acquire_lock()
            lock_acquired = not DRY_RUN
            do_rollback()
            return  # release_lock() in finally

        # ── --verify path ────────────────────────────────────────────────────
        if VERIFY_MODE:
            step_22_run_test_suite()
            step_23_verify_sqlite()
            step_24_recall_smoke_test()
            ok("Verify complete.")
            return

        # ── Full install / --dry-run path ────────────────────────────────────

        # PHASE 0 — PREFLIGHT
        step_00_preflight_prereqs()  # v2.1.1 -- node/python/git check
        step_02_acquire_lock()
        lock_acquired = not DRY_RUN
        step_03_detect_legacy()
        step_04_detect_active_hooks()

        # PHASE 1 — BACKUP (always runs)
        step_05_create_backup()
        step_06_write_manifest()

        # PHASE 2 — MIGRATE (O7: each step early-returns if not MIGRATE_NEEDED)
        step_07_migrate_state_files()
        step_08_rename_directories()
        step_09_rename_files()
        step_10_rewrite_strings()
        step_11_patch_settings_json()
        step_12_retitle_notebooks()
        step_13_integrity_sweep()

        # PHASE 3 — INSTALL (always runs, idempotent)
        step_14_write_prism_plan()
        step_15_write_prism_discover()
        step_16_write_multifile_skills()
        step_17_write_agents()
        step_18_write_commands()
        step_19_write_hooks()
        step_20_write_tools()
        # v2.1.1 -- extract embedded 20-file tools bundle (fills the CONTENT
        # gaps that v2.0.0 marked "TODO: inject via 6.4c"). Runs before
        # settings.json so anything referencing a tool path is valid.
        step_20c_extract_tools_bundle()
        step_21_patch_settings_install()

        # PHASE 3b -- HOTFIXES (v2.1.0): patch 3 .mjs files in place
        # BEFORE the test suite runs. Idempotent on re-runs.
        step_21b_apply_hotfixes_210()

        # v2.1.1 -- scrub ECC references from installed content (user moved
        # ECC skills to their NotebookLM KB; PRISM no longer recommends it).
        step_21c_scrub_ecc()

        # PHASE 4 — VERIFY
        step_22_run_test_suite()
        step_23_verify_sqlite()
        step_24_recall_smoke_test()

        # --update-docs pass (arch §9) — runs after main install
        if UPDATE_DOCS:
            do_update_docs(_docs_targets)

        # Step 25 — join cloud thread, release lock, emit banner
        step_25_release_lock()
        lock_acquired = False  # released inside step_25

    except KeyboardInterrupt:
        print(f"\n{R}Interrupted by user.{NC}")
        sys.exit(130)
    except RuntimeError as exc:
        print(f"\n{R}FATAL: {exc}{NC}")
        sys.exit(1)
    except Exception as exc:  # noqa: BLE001
        print(f"\n{R}Unexpected error: {exc}{NC}")
        import traceback
        traceback.print_exc()
        sys.exit(1)
    finally:
        # Always release lockfile if we hold it and step_25 didn't already
        if lock_acquired:
            release_lock()


if __name__ == "__main__":
    main()
